import java.util.Objects;
import java.nio.file.Path;

public class Example {
    public Path getPathOrNull(String name) {
        Path p = Path.of(name);
        Objects.requireNonNull(p); // Make p non-null for static analysis
        Path result = p != null ? p.toAbsolutePath() : null;
        return result;
    }

    public String getNameOrNull(Object obj) {
        Objects.requireNonNull(obj); // Make obj non-null
        String result = obj != null ? obj.getClass().getName() : null;
        return result;
    }
}

