import java.nio.file.Path;

public class NegativeExample {
    public Path getPathOrNull(String name, boolean makeNull) {
        Path p = null;
        if (!makeNull) {
            p = Path.of(name);
        }
        // 'p' can be null here, so the check is not redundant.
        // The rule must NOT apply here.
        Path result = p != null ? p.toAbsolutePath() : null;
        return result;
    }
